#include "tools/tokenize"

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Tokenize, DoubleQuotesGetTokenBasic)
{
  std::string cmd = "abc def";
  std::string token;
  std::string::size_type endIdx;
  EXPECT_TRUE(double_quotes_get_token(cmd, 0, endIdx, token));
  EXPECT_EQ(token, "abc");
  EXPECT_EQ(endIdx, 3);
}

TEST(Tokenize, DoubleQuotesGetTokenWithQuotes)
{
  std::string cmd = "\"abc def\" xyz";
  std::string token;
  std::string::size_type endIdx;
  EXPECT_TRUE(double_quotes_get_token(cmd, 0, endIdx, token));
  EXPECT_EQ(token, "abc def");
  EXPECT_EQ(endIdx, 9);
}

TEST(Tokenize, DoubleQuotesGetTokenLeadingSpaces)
{
  std::string cmd = "   \"abc def\" xyz";
  std::string token;
  std::string::size_type endIdx;
  EXPECT_TRUE(double_quotes_get_token(cmd, 0, endIdx, token));
  EXPECT_EQ(token, "abc def");
  EXPECT_EQ(endIdx, 12);
}

TEST(Tokenize, DoubleQuotesGetTokenUnclosedQuote)
{
  std::string cmd = "\"abc def xyz";
  std::string token;
  std::string::size_type endIdx;
  EXPECT_TRUE(double_quotes_get_token(cmd, 0, endIdx, token));
  EXPECT_EQ(token, "abc def xyz");
  EXPECT_EQ(endIdx, 13);
}

TEST(Tokenize, DoubleQuotesGetTokenEmpty)
{
  std::string cmd = "   ";
  std::string token;
  std::string::size_type endIdx;
  EXPECT_FALSE(double_quotes_get_token(cmd, 0, endIdx, token));
  EXPECT_EQ(token, "");
}

//---------------------------------------------------------------------------//
TEST(Tokenize, DoubleQuotesTokenizeBasic)
{
  std::string cmd = "aa bbb \"ccc ddd\" ee \"fff gg\"";
  std::vector<std::string> args;
  double_quotes_tokenize(cmd, args);
  ASSERT_EQ(args.size(), 5);
  EXPECT_EQ(args[0], "aa");
  EXPECT_EQ(args[1], "bbb");
  EXPECT_EQ(args[2], "ccc ddd");
  EXPECT_EQ(args[3], "ee");
  EXPECT_EQ(args[4], "fff gg");
}

TEST(Tokenize, DoubleQuotesTokenizeUnclosedQuote)
{
  std::string cmd = "aa \"bbb ccc";
  std::vector<std::string> args;
  double_quotes_tokenize(cmd, args);
  ASSERT_EQ(args.size(), 2);
  EXPECT_EQ(args[0], "aa");
  EXPECT_EQ(args[1], "bbb ccc");
}

TEST(Tokenize, DoubleQuotesTokenizeEmpty)
{
  std::string cmd = "";
  std::vector<std::string> args;
  double_quotes_tokenize(cmd, args);
  EXPECT_TRUE(args.empty());
}

//---------------------------------------------------------------------------//
TEST(Tokenize, WordsBasic)
{
  std::string s = "a,b,c";
  std::vector<std::string> words_vec;
  words(s, ",", false, words_vec);
  ASSERT_EQ(words_vec.size(), 3);
  EXPECT_EQ(words_vec[0], "a");
  EXPECT_EQ(words_vec[1], "b");
  EXPECT_EQ(words_vec[2], "c");
}

TEST(Tokenize, WordsTakeEmpty)
{
  std::string s = "a,,b";
  std::vector<std::string> words_vec;
  words(s, ",", true, words_vec);
  ASSERT_EQ(words_vec.size(), 3);
  EXPECT_EQ(words_vec[0], "a");
  EXPECT_EQ(words_vec[1], "");
  EXPECT_EQ(words_vec[2], "b");
}

TEST(Tokenize, WordsNoSeparator)
{
  std::string s = "abc";
  std::vector<std::string> words_vec;
  words(s, "", false, words_vec);
  ASSERT_EQ(words_vec.size(), 1);
  EXPECT_EQ(words_vec[0], "abc");
}

TEST(Tokenize, WordsEmptyString)
{
  std::string s = "";
  std::vector<std::string> words_vec;
  words(s, ",", false, words_vec);
  EXPECT_TRUE(words_vec.empty());
}

TEST(Tokenize, WordsMultiCharSeparator)
{
  std::string s = "a::b::c";
  std::vector<std::string> words_vec;
  words(s, "::", false, words_vec);
  ASSERT_EQ(words_vec.size(), 3);
  EXPECT_EQ(words_vec[0], "a");
  EXPECT_EQ(words_vec[1], "b");
  EXPECT_EQ(words_vec[2], "c");
}

TEST(Tokenize, WordsLeadingTrailingSeparator)
{
  std::string s = ",a,b,";
  std::vector<std::string> words_vec;
  words(s, ",", true, words_vec);
  ASSERT_EQ(words_vec.size(), 4);
  EXPECT_EQ(words_vec[0], "");
  EXPECT_EQ(words_vec[1], "a");
  EXPECT_EQ(words_vec[2], "b");
  EXPECT_EQ(words_vec[3], "");
}

TEST(Tokenize, WordsNoClear)
{
  std::string s = "a,b";
  std::vector<std::string> words_vec = {"x"};
  words(s, ",", false, words_vec, false);
  ASSERT_EQ(words_vec.size(), 3);
  EXPECT_EQ(words_vec[0], "x");
  EXPECT_EQ(words_vec[1], "a");
  EXPECT_EQ(words_vec[2], "b");
}

//---------------------------------------------------------------------------//
}  // namespace tools
